(function(){var btn=document.getElementById("wineMenuBtn");var trail=document.getElementById("wineNavTrail");var overlay=document.getElementById("slideMenuOverlay");if(!btn||!trail)return;function openMenu(){btn.classList.add("active");trail.classList.add("open");if(overlay)overlay.classList.add("active")}function closeMenu(){btn.classList.remove("active");trail.classList.remove("open");if(overlay)overlay.classList.remove("active")}btn.addEventListener("click",function(e){e.stopPropagation();if(trail.classList.contains("open"))closeMenu();else openMenu()});if(overlay)overlay.addEventListener("click",closeMenu);var syms=trail.querySelectorAll(".drink-sym");for(var i=0;i<syms.length;i++){syms[i].addEventListener("click",function(e){e.stopPropagation();var drinkIdx=parseInt(this.getAttribute("data-drink"));var scrollStart=0.12+drinkIdx*0.12;var scrollMax=document.body.scrollHeight-window.innerHeight;var target=scrollStart*scrollMax;window.scrollTo({top:target,behavior:"smooth"});setTimeout(closeMenu,300)})}document.addEventListener("keydown",function(e){if(e.key==="Escape"&&trail.classList.contains("open"))closeMenu()})})();